#!/usr/bin/env python3
# -*- coding: utf-8 -*-

# Author: Rensc
# Date: 2026-08-08
# Version: dev001
# Function: Summarize SeRP peak counts, lengths, transcript positions, and peak burdens.
# Input: SeRP peak table and per-codon profile generated by serp_peak.
# Output: Peak summary tables, normalized/full-length peak maps, and distribution figures.

"""Summary workflow for selective ribosome profiling peak-calling results."""

from __future__ import annotations

from collections import defaultdict
from pathlib import Path

import numpy as np
import pandas as pd

REQUIRED_PEAK_COLUMNS = {
    "transcripts",
    "gene_name",
    "peak_num",
    "peak_start",
    "peak_end",
}

OPTIONAL_NUMERIC_COLUMNS = [
    "peak_length",
    "gaps",
    "collision_start",
    "collision_end",
    "max_site",
    "max_fold",
    "mean_fold",
    "ck_peak_rpm",
    "ip_peak_rpm",
    "P_Value",
    "BHFDR",
]


class SeRPSummary:
    """Summarize called SeRP peaks and their transcript-relative distributions.

    Parameters
    ----------
    args : argparse.Namespace
        Parsed command-line arguments from ``serp_summary``.

    Notes
    -----
    Peak coordinates are interpreted as inclusive codon positions relative to the
    translation start, matching the current ``serp_peak`` output convention.
    Transcript span is recovered from ``*_peaks_ratio.txt`` so UTR positions are
    retained when present.
    """

    def __init__(self, args) -> None:
        """Initialize input/output paths and plotting settings."""
        self.input_prefix = args.input
        self.output_prefix = args.output if args.output else args.input + "_summary"
        self.peak_file = Path(self.input_prefix + "_peaks.txt")
        self.profile_file = Path(self.input_prefix + "_peaks_ratio.txt")
        self.normalized_bins = int(args.bins)
        self.profile_chunksize = int(args.chunksize)
        self.max_heatmap_cells = int(args.max_heatmap_cells)
        self.draw_plot = bool(args.plot)
        self.output_format = args.output_format
        self.dpi = int(args.dpi)
        self.font_size = float(args.font_size)

        self.peak_table = pd.DataFrame()
        self.transcript_span = pd.DataFrame()
        self.transcript_summary = pd.DataFrame()
        self.normalized_matrix = pd.DataFrame()
        self.inter_peak_distance = pd.DataFrame()

    @staticmethod
    def _safe_numeric(series: pd.Series) -> pd.Series:
        """Convert string values to numeric while treating ``-`` as missing."""
        return pd.to_numeric(series.replace("-", pd.NA), errors="coerce")

    def read_peaks(self) -> None:
        """Read, validate, and standardize called SeRP peaks."""
        peak = pd.read_csv(self.peak_file, sep="\t", dtype=str, low_memory=False)
        missing = sorted(REQUIRED_PEAK_COLUMNS.difference(peak.columns))
        if missing:
            raise ValueError(
                "Peak table is missing required column(s): {0}".format(
                    ", ".join(missing)
                )
            )

        peak = peak.copy()
        peak["transcripts"] = peak["transcripts"].astype(str)
        peak["gene_name"] = peak["gene_name"].fillna("-").astype(str)
        for column in ["peak_num", "peak_start", "peak_end"]:
            peak[column] = self._safe_numeric(peak[column])

        peak = peak.loc[
            peak["peak_num"].notna()
            & (peak["peak_num"] > 0)
            & peak["peak_start"].notna()
            & peak["peak_end"].notna()
        ].copy()

        if peak.empty:
            raise ValueError("No called peaks were found in {0}.".format(self.peak_file))

        peak["peak_num"] = peak["peak_num"].astype(int)
        peak["peak_start"] = peak["peak_start"].astype(int)
        peak["peak_end"] = peak["peak_end"].astype(int)

        invalid = peak["peak_end"] < peak["peak_start"]
        if invalid.any():
            example = peak.loc[
                invalid,
                ["transcripts", "peak_num", "peak_start", "peak_end"],
            ].head(5)
            raise ValueError(
                "Found peak_end < peak_start. Example:\n{0}".format(
                    example.to_string(index=False)
                )
            )

        for column in OPTIONAL_NUMERIC_COLUMNS:
            if column in peak.columns:
                peak[column] = self._safe_numeric(peak[column])

        peak["peak_span_length"] = peak["peak_end"] - peak["peak_start"] + 1
        if "peak_length" not in peak.columns:
            peak["peak_length"] = peak["peak_span_length"]
        else:
            peak["peak_length"] = peak["peak_length"].fillna(
                peak["peak_span_length"]
            )

        peak["peak_center"] = (peak["peak_start"] + peak["peak_end"]) / 2.0
        peak["peak_id"] = [
            "{0}:peak{1}:row{2}".format(transcript, peak_num, row_num + 1)
            for row_num, (transcript, peak_num) in enumerate(
                zip(peak["transcripts"], peak["peak_num"])
            )
        ]

        self.peak_table = peak.reset_index(drop=True)
        print("Called peaks: {0:,}".format(len(self.peak_table)), flush=True)
        print(
            "Transcripts with peaks: {0:,}".format(
                self.peak_table["transcripts"].nunique()
            ),
            flush=True,
        )

    def read_transcript_spans(self) -> None:
        """Stream the SeRP profile table and recover transcript coordinate spans.

        Only transcript names and ``from_tis`` coordinates are read. The full
        enrichment matrix is never loaded into memory.
        """
        target_transcripts = set(self.peak_table["transcripts"].astype(str).unique())
        span_min: dict[str, int] = {}
        span_max: dict[str, int] = {}
        observed_position_count: defaultdict[str, int] = defaultdict(int)

        header = pd.read_csv(self.profile_file, sep="\t", nrows=0)
        required = {"name", "from_tis"}
        missing = sorted(required.difference(header.columns))
        if missing:
            raise ValueError(
                "Profile table is missing required column(s): {0}".format(
                    ", ".join(missing)
                )
            )

        usecols = ["name", "from_tis"]
        for chunk in pd.read_csv(
            self.profile_file,
            sep="\t",
            usecols=usecols,
            chunksize=self.profile_chunksize,
        ):
            selected = chunk.loc[chunk["name"].astype(str).isin(target_transcripts)].copy()
            if selected.empty:
                continue

            selected["name"] = selected["name"].astype(str)
            selected["from_tis"] = pd.to_numeric(
                selected["from_tis"], errors="coerce"
            )
            selected = selected.dropna(subset=["from_tis"])
            selected["from_tis"] = selected["from_tis"].astype(int)

            for transcript, table in selected.groupby("name", sort=False):
                positions = table["from_tis"].to_numpy(dtype=int)
                current_min = int(positions.min())
                current_max = int(positions.max())
                span_min[transcript] = min(span_min.get(transcript, current_min), current_min)
                span_max[transcript] = max(span_max.get(transcript, current_max), current_max)
                observed_position_count[transcript] += int(len(positions))

        found = set(span_min)
        missing_transcripts = sorted(target_transcripts.difference(found))
        if missing_transcripts:
            example = ", ".join(missing_transcripts[:10])
            raise ValueError(
                "Profile coordinates are missing for {0:,} peak-containing transcript(s). "
                "Example: {1}".format(len(missing_transcripts), example)
            )

        rows = []
        discontinuous = 0
        for transcript in sorted(found):
            start = int(span_min[transcript])
            end = int(span_max[transcript])
            span_length = end - start + 1
            observed_count = int(observed_position_count[transcript])
            has_gap = observed_count != span_length
            discontinuous += int(has_gap)
            rows.append(
                {
                    "transcripts": transcript,
                    "transcript_start_from_tis": start,
                    "transcript_end_from_tis": end,
                    "transcript_length_codons": span_length,
                    "observed_position_count": observed_count,
                    "profile_has_coordinate_gap": has_gap,
                }
            )

        self.transcript_span = pd.DataFrame(rows)
        if discontinuous:
            print(
                "Warning: {0:,} transcript profile(s) have an observed row count inconsistent with "
                "their min/max coordinate span; span length is retained for positional mapping.".format(
                    discontinuous
                ),
                flush=True,
            )

    @staticmethod
    def _merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
        """Merge inclusive overlapping or adjacent integer intervals."""
        if not intervals:
            return []
        ordered = sorted(intervals)
        merged = [list(ordered[0])]
        for start, end in ordered[1:]:
            if start <= merged[-1][1] + 1:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
        return [(int(start), int(end)) for start, end in merged]

    @staticmethod
    def _classify_peak_locus(value: object) -> str:
        """Collapse historical peak-locus labels into broad region classes."""
        text = str(value).strip().lower()
        if text in {"utr5", "cds", "utr3"}:
            return text
        if text in {"", "-", "nan", "none"}:
            return "unknown"
        if "," in text:
            return "mixed"
        return text

    def calculate_summary(self) -> None:
        """Annotate peaks and calculate transcript-level peak burden metrics."""
        span = self.transcript_span.set_index("transcripts")
        peak = self.peak_table.copy()

        peak["transcript_start_from_tis"] = peak["transcripts"].map(
            span["transcript_start_from_tis"]
        )
        peak["transcript_end_from_tis"] = peak["transcripts"].map(
            span["transcript_end_from_tis"]
        )
        peak["transcript_length_codons"] = peak["transcripts"].map(
            span["transcript_length_codons"]
        )

        peak["peak_local_start"] = (
            peak["peak_start"] - peak["transcript_start_from_tis"]
        ).astype(int)
        peak["peak_local_end"] = (
            peak["peak_end"] - peak["transcript_start_from_tis"]
        ).astype(int)

        outside = (
            (peak["peak_local_start"] < 0)
            | (peak["peak_local_end"] >= peak["transcript_length_codons"])
        )
        if outside.any():
            example = peak.loc[
                outside,
                [
                    "transcripts",
                    "peak_num",
                    "peak_start",
                    "peak_end",
                    "transcript_start_from_tis",
                    "transcript_end_from_tis",
                ],
            ].head(5)
            raise ValueError(
                "Called peak coordinates fall outside the stored transcript profile. "
                "Example:\n{0}".format(example.to_string(index=False))
            )

        denominator = np.maximum(peak["transcript_length_codons"] - 1, 1)
        peak["peak_start_percent"] = peak["peak_local_start"] / denominator * 100.0
        peak["peak_end_percent"] = peak["peak_local_end"] / denominator * 100.0
        peak["peak_center_percent"] = (
            (peak["peak_local_start"] + peak["peak_local_end"]) / 2.0
        ) / denominator * 100.0
        if "Peak_loci" in peak.columns:
            peak["peak_region_class"] = peak["Peak_loci"].map(
                self._classify_peak_locus
            )
        else:
            peak["peak_region_class"] = "unknown"

        if "gaps" in peak.columns:
            peak["gap_fraction"] = peak["gaps"] / peak["peak_span_length"]
        if "collision_start" in peak.columns:
            peak["left_edge_extension"] = peak["peak_start"] - peak["collision_start"]
        if "collision_end" in peak.columns:
            peak["right_edge_extension"] = peak["collision_end"] - peak["peak_end"]
        if {"left_edge_extension", "right_edge_extension"}.issubset(peak.columns):
            peak["total_edge_extension"] = (
                peak["left_edge_extension"] + peak["right_edge_extension"]
            )

        self.peak_table = peak

        transcript_rows = []
        inter_peak_rows = []
        for transcript, table in peak.groupby("transcripts", sort=False):
            table = table.sort_values(["peak_start", "peak_end", "peak_num"], kind="stable")
            length = int(table["transcript_length_codons"].iloc[0])
            gene_names = table["gene_name"].dropna().astype(str).unique().tolist()
            gene_name = gene_names[0] if gene_names else "-"
            if len(gene_names) > 1:
                print(
                    "Warning: transcript {0} has multiple gene_name values: {1}".format(
                        transcript,
                        ",".join(gene_names),
                    ),
                    flush=True,
                )

            local_intervals = [
                (int(row.peak_local_start), int(row.peak_local_end))
                for row in table.itertuples()
            ]
            merged = self._merge_intervals(local_intervals)
            covered = sum(end - start + 1 for start, end in merged)
            weights = table["peak_span_length"].to_numpy(dtype=float)
            centers = table["peak_center_percent"].to_numpy(dtype=float)
            weighted_center = float(np.average(centers, weights=weights))

            for previous, current in zip(table.iloc[:-1].itertuples(), table.iloc[1:].itertuples()):
                gap = int(current.peak_start) - int(previous.peak_end) - 1
                inter_peak_rows.append(
                    {
                        "transcripts": transcript,
                        "gene_name": gene_name,
                        "left_peak_num": int(previous.peak_num),
                        "right_peak_num": int(current.peak_num),
                        "inter_peak_distance_codons": gap,
                    }
                )

            transcript_rows.append(
                {
                    "transcripts": transcript,
                    "gene_name": gene_name,
                    "transcript_start_from_tis": int(
                        table["transcript_start_from_tis"].iloc[0]
                    ),
                    "transcript_end_from_tis": int(
                        table["transcript_end_from_tis"].iloc[0]
                    ),
                    "transcript_length_codons": length,
                    "peak_count": int(len(table)),
                    "union_peak_span_codons": int(covered),
                    "peak_coverage_fraction": float(covered / length),
                    "peaks_per_100_codons": float(len(table) / length * 100.0),
                    "first_peak_center_percent": float(table["peak_center_percent"].iloc[0]),
                    "last_peak_center_percent": float(table["peak_center_percent"].iloc[-1]),
                    "weighted_peak_center_percent": weighted_center,
                    "mean_peak_span_length": float(table["peak_span_length"].mean()),
                    "max_peak_span_length": int(table["peak_span_length"].max()),
                }
            )

        transcript_summary = pd.DataFrame(transcript_rows)
        transcript_summary = transcript_summary.merge(
            self.transcript_span[
                ["transcripts", "observed_position_count", "profile_has_coordinate_gap"]
            ],
            on="transcripts",
            how="left",
            validate="one_to_one",
        )
        self.transcript_summary = transcript_summary
        self.inter_peak_distance = pd.DataFrame(inter_peak_rows)

    @staticmethod
    def _bin_interval_coverage(
        transcript_length: int,
        intervals: list[tuple[int, int]],
        bin_number: int,
    ) -> np.ndarray:
        """Calculate the fraction of every normalized bin covered by peak intervals."""
        coverage = np.zeros(bin_number, dtype=float)
        merged = SeRPSummary._merge_intervals(intervals)
        edges = np.linspace(0.0, float(transcript_length), bin_number + 1)

        for bin_index in range(bin_number):
            bin_start = edges[bin_index]
            bin_end = edges[bin_index + 1]
            bin_width = bin_end - bin_start
            if bin_width <= 0:
                continue
            overlap = 0.0
            for start, end in merged:
                interval_start = float(start)
                interval_end = float(end + 1)
                overlap += max(
                    0.0,
                    min(bin_end, interval_end) - max(bin_start, interval_start),
                )
            coverage[bin_index] = min(overlap / bin_width, 1.0)
        return coverage

    def build_normalized_matrix(self) -> None:
        """Build a transcript-by-bin matrix of normalized peak coverage."""
        summary = self.transcript_summary.sort_values(
            [
                "weighted_peak_center_percent",
                "first_peak_center_percent",
                "peak_count",
                "transcript_length_codons",
            ],
            ascending=[True, True, True, False],
            kind="stable",
        ).reset_index(drop=True)

        peak_group = {
            transcript: table
            for transcript, table in self.peak_table.groupby("transcripts", sort=False)
        }
        matrix = np.zeros((len(summary), self.normalized_bins), dtype=float)
        for row_index, row in summary.iterrows():
            transcript = str(row["transcripts"])
            table = peak_group[transcript]
            intervals = [
                (int(item.peak_local_start), int(item.peak_local_end))
                for item in table.itertuples()
            ]
            matrix[row_index, :] = self._bin_interval_coverage(
                transcript_length=int(row["transcript_length_codons"]),
                intervals=intervals,
                bin_number=self.normalized_bins,
            )

        columns = ["bin_{0:03d}".format(index + 1) for index in range(self.normalized_bins)]
        self.normalized_matrix = pd.DataFrame(matrix, columns=columns)
        self.normalized_matrix.insert(
            0,
            "weighted_peak_center_percent",
            summary["weighted_peak_center_percent"].to_numpy(),
        )
        self.normalized_matrix.insert(0, "gene_name", summary["gene_name"].to_numpy())
        self.normalized_matrix.insert(0, "transcripts", summary["transcripts"].to_numpy())
        self.normalized_matrix.insert(0, "row_order", np.arange(1, len(summary) + 1))

    def write_tables(self) -> None:
        """Write peak-level, transcript-level, distribution, and summary tables."""
        prefix = str(self.output_prefix)
        self.peak_table.to_csv(
            prefix + ".peaks.txt", sep="\t", index=False
        )
        self.transcript_summary.to_csv(
            prefix + ".transcripts.txt", sep="\t", index=False
        )
        self.normalized_matrix.to_csv(
            prefix + ".normalized_peak_matrix.txt", sep="\t", index=False
        )
        full_length_order = self.transcript_summary.sort_values(
            ["transcript_length_codons", "weighted_peak_center_percent"],
            ascending=[False, True],
            kind="stable",
        ).reset_index(drop=True)
        full_length_order.insert(0, "row_order", np.arange(1, len(full_length_order) + 1))
        full_length_order.to_csv(
            prefix + ".full_length_heatmap_order.txt", sep="\t", index=False
        )

        peak_length_distribution = (
            self.peak_table.groupby("peak_length", dropna=False)
            .size()
            .rename("peak_count")
            .reset_index()
            .sort_values("peak_length", kind="stable")
        )
        peak_length_distribution.to_csv(
            prefix + ".peak_length_distribution.txt", sep="\t", index=False
        )

        peak_count_distribution = (
            self.transcript_summary.groupby("peak_count")
            .size()
            .rename("transcript_count")
            .reset_index()
            .sort_values("peak_count", kind="stable")
        )
        peak_count_distribution.to_csv(
            prefix + ".peak_count_distribution.txt", sep="\t", index=False
        )

        region_distribution = (
            self.peak_table.groupby("peak_region_class")
            .size()
            .rename("peak_count")
            .reset_index()
            .sort_values("peak_count", ascending=False, kind="stable")
        )
        region_distribution["peak_fraction"] = (
            region_distribution["peak_count"] / len(self.peak_table)
        )
        region_distribution.to_csv(
            prefix + ".peak_region_distribution.txt", sep="\t", index=False
        )

        if not self.inter_peak_distance.empty:
            self.inter_peak_distance.to_csv(
                prefix + ".inter_peak_distance.txt", sep="\t", index=False
            )

        metrics: list[tuple[str, object]] = []
        peak = self.peak_table
        tx = self.transcript_summary
        valid_gene = peak["gene_name"].astype(str).str.strip()
        valid_gene = valid_gene.loc[~valid_gene.isin(["", "-", "nan", "None"])]
        metrics.extend(
            [
                ("total_peak_count", len(peak)),
                ("transcript_with_peak_count", peak["transcripts"].nunique()),
                ("gene_with_peak_count", valid_gene.nunique()),
                ("single_peak_transcript_count", int((tx["peak_count"] == 1).sum())),
                ("multi_peak_transcript_count", int((tx["peak_count"] > 1).sum())),
                ("mean_peaks_per_transcript", tx["peak_count"].mean()),
                ("median_peaks_per_transcript", tx["peak_count"].median()),
                ("max_peaks_per_transcript", tx["peak_count"].max()),
                ("mean_peak_core_length", peak["peak_length"].mean()),
                ("median_peak_core_length", peak["peak_length"].median()),
                ("mean_peak_span_length", peak["peak_span_length"].mean()),
                ("median_peak_span_length", peak["peak_span_length"].median()),
                ("min_peak_span_length", peak["peak_span_length"].min()),
                ("max_peak_span_length", peak["peak_span_length"].max()),
                ("mean_peak_center_percent", peak["peak_center_percent"].mean()),
                ("median_peak_center_percent", peak["peak_center_percent"].median()),
                ("mean_peak_coverage_fraction", tx["peak_coverage_fraction"].mean()),
                ("median_peak_coverage_fraction", tx["peak_coverage_fraction"].median()),
                ("mean_peaks_per_100_codons", tx["peaks_per_100_codons"].mean()),
                ("median_peaks_per_100_codons", tx["peaks_per_100_codons"].median()),
            ]
        )

        if "max_fold" in peak.columns and peak["max_fold"].notna().any():
            metrics.extend(
                [
                    ("mean_max_fold", peak["max_fold"].mean()),
                    ("median_max_fold", peak["max_fold"].median()),
                ]
            )
        if "mean_fold" in peak.columns and peak["mean_fold"].notna().any():
            metrics.extend(
                [
                    ("mean_mean_fold", peak["mean_fold"].mean()),
                    ("median_mean_fold", peak["mean_fold"].median()),
                ]
            )
        if "gap_fraction" in peak.columns and peak["gap_fraction"].notna().any():
            metrics.extend(
                [
                    ("mean_gap_fraction", peak["gap_fraction"].mean()),
                    ("median_gap_fraction", peak["gap_fraction"].median()),
                ]
            )
        if "total_edge_extension" in peak.columns and peak["total_edge_extension"].notna().any():
            metrics.extend(
                [
                    ("mean_total_edge_extension", peak["total_edge_extension"].mean()),
                    ("median_total_edge_extension", peak["total_edge_extension"].median()),
                ]
            )
        if not self.inter_peak_distance.empty:
            distance = self.inter_peak_distance["inter_peak_distance_codons"]
            metrics.extend(
                [
                    ("mean_inter_peak_distance", distance.mean()),
                    ("median_inter_peak_distance", distance.median()),
                    ("min_inter_peak_distance", distance.min()),
                    ("max_inter_peak_distance", distance.max()),
                ]
            )

        metric_table = pd.DataFrame(metrics, columns=["metric", "value"])
        metric_table.to_csv(prefix + ".summary.txt", sep="\t", index=False)

    def draw_figures(self) -> None:
        """Generate all default SeRP summary figures through the plotting layer."""
        if not self.draw_plot:
            return
        from utils.serp.SummaryPlot import SeRPSummaryPlot

        plotter = SeRPSummaryPlot(
            peak_table=self.peak_table,
            transcript_summary=self.transcript_summary,
            normalized_matrix=self.normalized_matrix,
            inter_peak_distance=self.inter_peak_distance,
            output_prefix=self.output_prefix,
            normalized_bins=self.normalized_bins,
            max_heatmap_cells=self.max_heatmap_cells,
            output_format=self.output_format,
            dpi=self.dpi,
            font_size=self.font_size,
        )
        plotter.draw_all()

    def run(self) -> None:
        """Run the complete SeRP peak-summary workflow."""
        self.read_peaks()
        self.read_transcript_spans()
        self.calculate_summary()
        self.build_normalized_matrix()
        self.write_tables()
        self.draw_figures()